namespace ctr {namespace {
using Bytes=std::vector<std::byte>;
void need(bool ok,const char* message){if(!ok)throw std::invalid_argument(message);}
std::span<const std::byte> slice(std::span<const std::byte> b,std::uint64_t off,std::uint64_t length){need(off<=b.size()&&length<=b.size()-off,"Original file range exceeds extent");return b.subspan(static_cast<std::size_t>(off),static_cast<std::size_t>(length));}
template<class T>T read(std::span<const std::byte> b,std::uint64_t off){T v{};auto s=slice(b,off,sizeof(T));std::memcpy(&v,s.data(),sizeof(T));return v;}
Bytes file(const std::filesystem::path& p){std::ifstream in(p,std::ios::binary|std::ios::ate);need(static_cast<bool>(in),"Original file unavailable");const auto n=in.tellg();need(n>0&&n<=0x20000000,"Bounded original file size required");Bytes b(static_cast<std::size_t>(n));in.seekg(0);in.read(reinterpret_cast<char*>(b.data()),static_cast<std::streamsize>(b.size()));need(static_cast<bool>(in),"Original file truncated");return b;}
std::string hash(std::span<const std::byte> b){BCRYPT_ALG_HANDLE algorithm{};if(BCryptOpenAlgorithmProvider(&algorithm,BCRYPT_SHA256_ALGORITHM,nullptr,0)<0)throw std::runtime_error("SHA256 provider unavailable");std::array<unsigned char,32> digest{};const auto status=BCryptHash(algorithm,nullptr,0,reinterpret_cast<PUCHAR>(const_cast<std::byte*>(b.data())),static_cast<ULONG>(b.size()),digest.data(),static_cast<ULONG>(digest.size()));BCryptCloseAlgorithmProvider(algorithm,0);if(status<0)throw std::runtime_error("Original SHA256 failed");constexpr char alphabet[]="0123456789abcdef";std::string result;for(auto v:digest){result+=alphabet[v>>4];result+=alphabet[v&15];}return result;}
struct Program {std::uint32_t type;std::uint64_t offset,address,filesize,memsize;};
std::vector<Program> programs(std::span<const std::byte> image,std::uint64_t base){need(read<std::uint32_t>(image,base)==0x464c457f&&read<std::uint8_t>(image,base+4)==2&&read<std::uint8_t>(image,base+5)==1,"Original little-endian ELF64 required");const auto off=read<std::uint64_t>(image,base+32);const auto stride=read<std::uint16_t>(image,base+54),count=read<std::uint16_t>(image,base+56);need(stride==56&&count&&count<256,"Invalid original ELF program headers");std::vector<Program> result;for(std::uint64_t i=0;i<count;++i){const auto at=base+off+i*stride;slice(image,at,56);result.push_back({read<std::uint32_t>(image,at),read<std::uint64_t>(image,at+8),read<std::uint64_t>(image,at+16),read<std::uint64_t>(image,at+32),read<std::uint64_t>(image,at+40)});}return result;}
struct Segment {std::uint64_t flags,offset,size;};
std::span<const std::byte> self_range(std::span<const std::byte> image,const std::vector<Segment>& segments,const std::vector<Program>& ph,std::uint64_t off,std::uint64_t size){for(auto s:segments){if(!(s.flags&0x800))continue;const auto index=(s.flags>>20)&4095;need(index<ph.size(),"SELF segment header index invalid");const auto h=ph[static_cast<std::size_t>(index)];if(off>=h.offset&&off-h.offset<=h.filesize&&size<=h.filesize-(off-h.offset)){need(!(s.flags&10),"Encrypted/compressed SELF range unsupported");need(off-h.offset<=s.size&&size<=s.size-(off-h.offset),"Plain SELF segment truncated");return slice(image,s.offset+off-h.offset,size);}}throw std::invalid_argument("Original SELF range not plaintext-backed");}
std::uint64_t tag(std::span<const std::byte> dynamic,std::uint64_t key){need(dynamic.size()%16==0,"Dynamic table alignment invalid");for(std::size_t i=0;i<dynamic.size();i+=16)if(read<std::uint64_t>(dynamic,i)==key)return read<std::uint64_t>(dynamic,i+8);throw std::invalid_argument("Required SELF dynamic tag missing");}
Program find(const std::vector<Program>& ph,std::uint32_t type){for(auto h:ph)if(h.type==type)return h;throw std::invalid_argument("Original program header missing");}
Bytes selected(std::span<const std::byte> flat,const std::vector<Program>& ph,std::uint64_t address,std::uint64_t size){for(auto h:ph)if(h.type==1&&address>=h.address&&address-h.address<=h.filesize&&size<=h.filesize-(address-h.address)){auto b=slice(flat,h.offset+address-h.address,size);return Bytes(b.begin(),b.end());}throw std::invalid_argument("Selected section not ELF PT_LOAD-backed");}
void relocate(Bytes& bytes,std::uint64_t address,std::span<const std::byte> rows,std::span<const std::byte> dynlib,std::uint64_t symoff,std::uint64_t stroff,unsigned& count,unsigned& unresolved){need(rows.size()%24==0,"Original RELA extent invalid");for(std::size_t i=0;i<rows.size();i+=24){const auto offset=read<std::uint64_t>(rows,i);if(offset<address||offset-address>=bytes.size())continue;const auto info=read<std::uint64_t>(rows,i+8),addend=read<std::uint64_t>(rows,i+16);slice(bytes,offset-address,8);++count;if(info==8){std::memcpy(bytes.data()+offset-address,&addend,8);continue;}need(static_cast<std::uint32_t>(info)==1&&offset==0x02200048,"Unsupported selected relocation");const auto symbol=symoff+(info>>32)*24;need(read<std::uint16_t>(dynlib,symbol+6)==0&&read<std::uint64_t>(dynlib,symbol+8)==0&&addend==0,"Unexpected external symbol definition");constexpr char expected[]="P330P3dFF68#BI#z";const auto n=stroff+read<std::uint32_t>(dynlib,symbol);auto name=slice(dynlib,n,sizeof(expected));need(!std::memcmp(name.data(),expected,sizeof(expected)),"Unresolved symbol identity changed");need(read<std::uint64_t>(bytes,offset-address)==0,"Unresolved symbol plaintext is not zero");++unresolved; /* Preserve genuine unresolved cell; no success binding. */}}
void* readonly(const Bytes& b){void* p=VirtualAlloc(nullptr,4096,MEM_RESERVE|MEM_COMMIT,PAGE_READWRITE);if(!p)throw std::runtime_error("ProcParam owned memory unavailable");std::memcpy(p,b.data(),b.size());DWORD old{};if(!VirtualProtect(p,4096,PAGE_READONLY,&old)){VirtualFree(p,0,MEM_RELEASE);throw std::runtime_error("ProcParam protection failed");}return p;}
}
NativeProcParam::~NativeProcParam(){if(root_)VirtualFree(root_,0,MEM_RELEASE);if(libc_)VirtualFree(libc_,0,MEM_RELEASE);}
std::shared_ptr<const NativeProcParam> NativeProcParam::load(const std::filesystem::path& self,const std::filesystem::path& flat){const auto s=file(self),f=file(flat);need(hash(s)=="ca9c94411375ebec52de70fbc62f605ac8e2cea95595c627029969b5b9d9b5b1"&&hash(f)=="3e0158933a6bf690cf386f5ab846b0ef7b3d30ff8fc75c420d0dc41736fc4b9a","Original source identity mismatch");need(read<std::uint32_t>(s,0)==0x1d3d154f,"Original SELF magic required");const auto n=read<std::uint16_t>(s,24);need(n>0&&n<256,"SELF segment count invalid");std::vector<Segment> segments;for(std::uint64_t i=0;i<n;++i){const auto at=32+i*32;segments.push_back({read<std::uint64_t>(s,at),read<std::uint64_t>(s,at+8),read<std::uint64_t>(s,at+16)});}const auto ph=programs(s,32+static_cast<std::uint64_t>(n)*32),fh=programs(f,0);const auto p=find(ph,0x61000001);need(p.address==0x02600000&&p.memsize==88,"Original ProcParam root differs");const auto dh=find(ph,2),lh=find(ph,0x61000000);const auto dynamic=self_range(s,segments,ph,dh.offset,dh.filesize),dynlib=self_range(s,segments,ph,lh.offset,lh.filesize);const auto rows=slice(dynlib,tag(dynamic,0x6100002f),tag(dynamic,0x61000031));auto root=selected(f,fh,p.address,88),libc=selected(f,fh,0x02200000,496);unsigned count=0,unresolved=0;const auto symoff=tag(dynamic,0x61000039),stroff=tag(dynamic,0x61000035);relocate(root,p.address,rows,dynlib,symoff,stroff,count,unresolved);relocate(libc,0x02200000,rows,dynlib,symoff,stroff,count,unresolved);need(count==27&&unresolved==1,"Selected original relocation counts differ");need(read<std::uint64_t>(root,0)==88&&read<std::uint64_t>(root,0x38)==0x02200000&&read<std::uint64_t>(root,0x40)==0x02200090&&read<std::uint64_t>(root,0x48)==0x022000c8&&read<std::uint64_t>(libc,0)==144,"Original section graph differs");auto owner=std::shared_ptr<NativeProcParam>(new NativeProcParam);owner->root_=readonly(root);owner->libc_=readonly(libc);return owner;}
std::span<const std::byte> NativeProcParam::page(std::uint64_t logical) const {const void* p=logical==0x02600000?root_:logical==0x02200000?libc_:nullptr;need(p!=nullptr,"ProcParam translation outside selected pages");return {static_cast<const std::byte*>(p),4096};}
std::span<const std::byte> NativeProcParam::section(std::uint64_t logical) const {return page(logical).first(logical==0x02600000?88:496);}
}
